<template>
  <div class="app-container">
    <div class="page-hero"><div class="hero-inner"><div class="hero-text"><h1 class="hero-title">随机区组设计方差分析</h1><p class="hero-desc">双因素方差分析（无交互作用），将总变异分解为处理效应、区组效应和误差三部分，通过 F 检验分别判断处理因素和区组因素是否有显著效应</p></div><el-tag class="hero-tag" effect="dark" round>ANOVA · RANDOMIZED BLOCK</el-tag></div></div>
    <el-row :gutter="20" class="mb-4 input-row">
      <el-col :lg="16" :xs="24"><el-card shadow="never" class="input-card"><el-form label-position="top"><el-form-item label="数据（每行一个区组，列为不同处理，逗号分隔）"><el-input v-model="form.rawData" type="textarea" :rows="5" /></el-form-item></el-form><div class="action-bar"><el-button type="primary" class="calc-btn" @click="calculate"><el-icon class="mr-1"><DataAnalysis /></el-icon>开始计算</el-button><el-button class="reset-btn" @click="loadDemo">加载示例</el-button><el-button class="reset-btn" @click="clearAll">清除</el-button></div></el-card></el-col>
      <el-col :lg="8" :xs="24"><div class="param-sidebar"><div class="param-sidebar-header"><el-icon class="sidebar-icon"><InfoFilled /></el-icon>检验原理</div><div class="principle-content"><div class="principle-block"><div class="principle-label">假设</div><p>H₀(处理): 各处理效果相同</p><p>H₀(区组): 各区组无差异</p></div><div class="principle-block"><div class="principle-label">变异分解</div><div class="formula-box">SST = SS处理 + SS区组 + SSE</div></div></div><div class="ref-section"><div class="ref-title">参考文献</div><p class="ref-item">[1] 方积乾.《卫生统计学》第7版, 2012.</p></div></div></el-col>
    </el-row>
    <transition name="result-fade"><div v-if="res" class="result-section">
      <div class="metrics-grid mb-5"><div v-for="m in metrics" :key="m.label" class="metric-card" :class="m.type"><div class="metric-indicator" /><div class="metric-label">{{ m.label }}</div><div class="metric-value">{{ m.value }}</div></div></div>
      <el-card shadow="never" class="detail-card mb-4"><template #header><div class="card-header-inner"><el-icon class="header-icon"><Document /></el-icon><span class="font-bold">方差分析表</span></div></template><el-table :data="anovaTable" size="small" stripe border><el-table-column prop="source" label="来源" width="80" /><el-table-column prop="ss" label="SS" /><el-table-column prop="df" label="df" width="50" /><el-table-column prop="ms" label="MS" /><el-table-column prop="f" label="F" /><el-table-column prop="p" label="P" /></el-table></el-card>
    </div></transition>
  </div>
</template>
<script setup lang="ts">
import { InfoFilled, DataAnalysis, Document } from "@element-plus/icons-vue"; import * as S from "../utils/stats";
defineOptions({ name: "ANOVABlock" }); const form = reactive({ rawData: "" }); const res = ref(false); const metrics = ref<any[]>([]); const anovaTable = ref<any[]>([]);
function loadDemo() { form.rawData = "6.1,5.2,4.8\n7.3,6.4,5.9\n5.8,4.9,4.5\n6.9,6.0,5.6\n7.1,6.3,5.7"; calculate(); }
function clearAll() { form.rawData = ""; res.value = false; }
function calculate() {
  const matrix = form.rawData.trim().split("\n").map(l => S.parseNumbers(l)); const b = matrix.length, k = matrix[0]?.length || 0; if (b < 2 || k < 2) return;
  const N = b * k, grand = matrix.flat(), grandMean = S.mean(grand);
  const colMeans = Array.from({ length: k }, (_, j) => S.mean(matrix.map(row => row[j]))); const rowMeans = matrix.map(row => S.mean(row));
  let SST = 0, SSR = 0, SSC = 0; grand.forEach(v => SST += (v - grandMean) ** 2); rowMeans.forEach(rm => SSR += k * (rm - grandMean) ** 2); colMeans.forEach(cm => SSC += b * (cm - grandMean) ** 2);
  const SSE = SST - SSR - SSC, dfR = b - 1, dfC = k - 1, dfE = (b - 1) * (k - 1), dfT = N - 1;
  const MSR = SSR / dfR, MSC = SSC / dfC, MSE = dfE > 0 ? SSE / dfE : 0;
  const fTreat = MSE > 0 ? MSC / MSE : 0, fBlock = MSE > 0 ? MSR / MSE : 0;
  const pTreat = S.fTestPValue(fTreat, dfC, dfE), pBlock = S.fTestPValue(fBlock, dfR, dfE); const sig = pTreat < 0.05; res.value = true;
  metrics.value = [{ label: "区组数", value: b, type: "accent" }, { label: "处理数", value: k, type: "accent" }, { label: "F(处理)", value: S.fmt(fTreat), type: "warning" }, { label: "P(处理)", value: S.fmtP(pTreat), type: sig ? "warning" : "neutral" }, { label: "F(区组)", value: S.fmt(fBlock), type: "success" }, { label: "P(区组)", value: S.fmtP(pBlock), type: "success" }];
  anovaTable.value = [{ source: "处理", ss: S.fmt(SSC), df: dfC, ms: S.fmt(MSC), f: S.fmt(fTreat), p: S.fmtP(pTreat) }, { source: "区组", ss: S.fmt(SSR), df: dfR, ms: S.fmt(MSR), f: S.fmt(fBlock), p: S.fmtP(pBlock) }, { source: "误差", ss: S.fmt(SSE), df: dfE, ms: S.fmt(MSE), f: "", p: "" }, { source: "总计", ss: S.fmt(SST), df: dfT, ms: "", f: "", p: "" }];
}
</script>
